{"task_id": "T06", "code": "def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings, each token is an integer or an operator '+', '-', '*', '/'.
    Division should truncate toward zero.
    Returns the integer result.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero: use int() on true division result
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                stack.append(int(a / b))
        else:
            # token is a number, possibly with sign
            stack.append(int(token))
    return stack[-1] if stack else 0"}

