    """Count islands in a possibly jagged binary grid.
    Uses 4-directional adjacency. Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < len(grid[r])
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if not in_bounds(x, y) or grid[x][y] != 1:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited:
                    stack.append((nx, ny))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
