def solve(tokens):
    """Evaluate Reverse Polish Notation expression handling +,-,*,/ with truncation toward zero."""
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Python int division truncates toward zero via int(a / b)
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

