def solve(grid):
    """Count the number of islands in a 2D grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    The grid may be empty or have rows of differing lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            for nr, nc in neighbors(cr, cc):
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))
    islands = 0
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 1 and (r, c) not in visited:
                islands += 1
                dfs(r, c)
    return islands
}

