def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero (i.e., the result of int(a / b) in Python).
    This implementation avoids floating‑point overflow by using integer arithmetic.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
