    import bisect
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # Find insertion point (first >= x) for strict increasing we need >, so use bisect_left on x
        # To maintain strictly increasing, we replace first element >= x with x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

