    # Return a new list representing the next permutation.
    # Handle trivial cases
    if len(nums) <= 1:
        return list(nums)
    a = list(nums)  # work on a copy
    n = len(a)
    # Find the first index i from the right such that a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
