def solve(tokens):
    """Evaluate Reverse Polish Notation with truncating division toward zero.
    Supports integers and the operators '+', '-', '*', '/'.
    """
    stack = []
    for token in tokens:
        if token not in '+-*/':
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero without using float conversion
                if b == 0:
                    raise ZeroDivisionError("division by zero in RPN expression")
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
    return stack[0] if stack else 0
}

